u19-tile-scroll.value-editor:
pv.addEventListener('click', () => {
  const inp = document.createElement('input'); inp.type = 'text'; inp.value = S[key];
  inp.style.cssText = 'width:52px;flex:0 0 52px;background:var(--panel2);border:1px solid var(--accent);border-radius:3px;color:var(--text);font:10px var(--mono);padding:1px 3px;text-align:right';
  pv.replaceWith(inp); inp.focus(); inp.select();
  let closed = false;
  const done = ok => { if (closed) return; closed = true; if (ok){ const n = parseFloat(inp.value); if (!isNaN(n)){ S[key] = Math.min(max, Math.max(min, n)); changed(key); } } inp.replaceWith(pv); syncUI(); };
  inp.addEventListener('keydown', e => { if (e.key==='Enter') done(true); if (e.key==='Escape') done(false); e.stopPropagation(); });
  inp.addEventListener('blur', () => done(true), { once:true });
});

flame-transition.media-boundary:
function loadFile(key,file){
  if(!file) return;
  const isVid=file.type.startsWith("video/")||/\.(mov|mp4|webm|m4v)$/i.test(file.name);
  if(!isVid&&!file.type.startsWith("image/")) return toast("画像または動画ファイルを選んでください");
  const sc=scenes[key];
  if(isVideo(sc)) sc.media.pause();
  if(sc.url) URL.revokeObjectURL(sc.url);
  const url=URL.createObjectURL(file); sc.url=url;
  const done=el=>{ sc.media=el; sc.name=file.name; $("name"+key).textContent=file.name; sc.redraw=true; layoutTrack(); syncVideos(true); if(!playing) render(playhead); toast(`シーン${key}を差し替えました`); };
  if(isVid){
    const v=document.createElement("video"); v.src=url; v.muted=true; v.loop=false; v.playsInline=true; v.preload="auto";
    v.addEventListener("loadeddata",()=>done(v),{once:true});
    v.addEventListener("error",()=>toast("この動画は読み込めませんでした（H.264のMP4かWebMを試してください）"),{once:true});
  }else{
    const im=new Image(); im.onload=()=>done(im); im.onerror=()=>toast("画像を読み込めませんでした"); im.src=url;
  }
}

u19-hud-sequence.media-history:
async function setClip(file) {
  if (EX.on) { toast('書き出し中は差し替えできません'); return; }
  if (!file || !/^video\//.test(file.type || 'video/')) { toast('動画ファイルを選んでください'); return; }
  const url = URL.createObjectURL(file);
  const ok = await new Promise((res) => {
    const done = (v) => { clip.removeEventListener('loadeddata', onOk); clip.removeEventListener('error', onErr); res(v); };
    const onOk = () => done(true), onErr = () => done(false);
    clip.addEventListener('loadeddata', onOk); clip.addEventListener('error', onErr);
    clip.src = url; clip.load();
  });
  if (!ok) { URL.revokeObjectURL(url); toast('この動画は読み込めませんでした（MP4 / WebM / MOV(H.264) を試してください）'); resetClip(true); return; }
  if (userURL) URL.revokeObjectURL(userURL);
  userURL = url; clipName = file.name; resetBtn.disabled = false; showInfo();
  toast(`${file.name} に差し替えました`); play();
}
function resetClip(quiet) {
  if (EX.on) return;
  if (userURL) { URL.revokeObjectURL(userURL); userURL = null; }
  clip.removeAttribute('src'); clip.load();
  clipName = 'u19-window.mp4（最初の映像）'; resetBtn.disabled = true;
  if (!quiet) { toast('最初の映像に戻しました'); clip.addEventListener('loadeddata', () => play(), { once: true }); }
}
